/**
 * SePay bank-transfer webhook parsing and verification.
 *
 * SePay posts a JSON envelope after each bank transaction and authenticates the request with
 * `Authorization: Apikey <secret>`. Everything here is pure so the route handler only has to deal
 * with HTTP concerns.
 */

/** Order codes are generated by `create_multi_product_booking` as `AIR-YYMMDD-XXXXXXXX`. */
export const ORDER_CODE_PATTERN = /AIR-\d{6}-[A-F0-9]{8}/

export interface SePayTransfer {
  /** Provider transaction id; the database keeps this unique per provider for idempotency. */
  externalId: string
  amountVnd: number
  content: string
  payload: Record<string, unknown>
}

export type SePayParseResult =
  | { ok: true; transfer: SePayTransfer }
  | { ok: false; reason: 'invalid-payload' | 'not-incoming' | 'invalid-amount' }

/** Extracts the first rental order code from a bank transfer description. */
export function findOrderCode(content: string | null | undefined): string | null {
  if (!content) return null
  const match = ORDER_CODE_PATTERN.exec(content.toUpperCase())
  return match ? match[0] : null
}

/** Validates the SePay envelope before anything touches the database. */
export function parseSePayWebhook(input: unknown): SePayParseResult {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, reason: 'invalid-payload' }
  }
  const payload = input as Record<string, unknown>
  const id = payload.id
  // SePay sends a number today; accept a numeric string so a format change cannot silently drop
  // real transfers into an infinite retry loop.
  const externalId =
    typeof id === 'number' && Number.isSafeInteger(id) && id > 0
      ? String(id)
      : typeof id === 'string' && /^\d{1,40}$/.test(id)
        ? id
        : null
  if (!externalId) return { ok: false, reason: 'invalid-payload' }

  const transferType = payload.transferType
  if (transferType !== 'in') return { ok: false, reason: 'not-incoming' }

  const amount = payload.transferAmount
  if (typeof amount !== 'number' || !Number.isSafeInteger(amount) || amount <= 0) {
    return { ok: false, reason: 'invalid-amount' }
  }

  const content =
    typeof payload.content === 'string'
      ? payload.content
      : typeof payload.description === 'string'
        ? payload.description
        : ''

  return {
    ok: true,
    transfer: {
      externalId,
      amountVnd: amount,
      content: content.slice(0, 1000),
      payload,
    },
  }
}

/**
 * Compares the `Authorization` header with the configured secret. The comparison runs on equal-length
 * buffers so a mismatching secret cannot leak its prefix through response timing.
 */
export function sePayAuthorizationMatches(
  header: string | null | undefined,
  secret: string | null | undefined,
): boolean {
  if (!header || !secret) return false
  const expected = `Apikey ${secret}`
  if (header.length !== expected.length) return false
  const provided = Buffer.from(header, 'utf8')
  const wanted = Buffer.from(expected, 'utf8')
  if (provided.length !== wanted.length) return false
  let diff = 0
  for (let index = 0; index < provided.length; index += 1) {
    diff |= provided[index] ^ wanted[index]
  }
  return diff === 0
}

/** Payments stay off until the deployment is explicitly configured for them. */
export function paymentsEnabled(): boolean {
  return process.env.AIR_ENABLE_PAYMENTS === 'true'
}

export interface BankTransferInfo {
  bankName: string
  accountNumber: string
  accountName: string
}

/**
 * Bank account shown on the order page. Returns null when the deployment has not configured a
 * receiving account, so the UI can show "contact the shop" instead of an empty card.
 */
export function bankTransferInfo(): BankTransferInfo | null {
  const bankName = process.env.AIR_BANK_NAME?.trim()
  const accountNumber = process.env.AIR_BANK_ACCOUNT_NUMBER?.trim()
  const accountName = process.env.AIR_BANK_ACCOUNT_NAME?.trim()
  if (!bankName || !accountNumber || !accountName) return null
  return { bankName, accountNumber, accountName }
}

/** Human-readable transfer memo that still contains the code the webhook looks for. */
export function transferMemo(orderCode: string): string {
  return `THANH TOAN ${orderCode}`
}
